CREATE TABLE credentials(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),subject_type varchar(20) NOT NULL CHECK(subject_type IN('student','employee')),student_id uuid REFERENCES students(id),employee_id uuid REFERENCES employees(id),credential_type varchar(20) NOT NULL CHECK(credential_type IN('qr','rfid','nfc','barcode')),value_digest char(64) NOT NULL,display_suffix varchar(12),issued_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz,status varchar(20) NOT NULL DEFAULT 'active' CHECK(status IN('active','suspended','revoked','expired')),revoked_at timestamptz,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1,CHECK((subject_type='student' AND student_id IS NOT NULL AND employee_id IS NULL)OR(subject_type='employee' AND employee_id IS NOT NULL AND student_id IS NULL)));
CREATE UNIQUE INDEX credential_digest_active_key ON credentials(value_digest) WHERE status='active';CREATE INDEX credential_student_idx ON credentials(student_id)WHERE student_id IS NOT NULL;CREATE INDEX credential_employee_idx ON credentials(employee_id)WHERE employee_id IS NOT NULL;
CREATE TABLE attendance_terminals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code varchar(60) NOT NULL UNIQUE,name varchar(120) NOT NULL,location varchar(200),status varchar(20) NOT NULL DEFAULT 'active' CHECK(status IN('active','inactive','revoked')),last_seen_at timestamptz,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1);
CREATE TABLE attendance_terminal_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),terminal_id uuid NOT NULL REFERENCES attendance_terminals(id),client_event_id uuid NOT NULL,captured_at timestamptz NOT NULL,credential_digest char(64) NOT NULL,capture_method varchar(20) NOT NULL CHECK(capture_method IN('qr','rfid','nfc','barcode')),subject_type varchar(20),subject_id uuid,outcome varchar(20) NOT NULL CHECK(outcome IN('accepted','rejected')),message varchar(300) NOT NULL,attendance_record_id uuid,processed_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES users(id),UNIQUE(terminal_id,client_event_id));CREATE INDEX terminal_events_time_idx ON attendance_terminal_events(terminal_id,captured_at DESC);
